def ctc_forward(probs, target, blank=0):
    T, C = probs.shape
    S = len(target)

    extended = []
    for y in target:
        extended.append(blank)
        extended.append(y)
    extended.append(blank)
    L = len(extended)

    alpha = np.zeros((T, L))
    alpha[0][0] = probs[0][extended[0]]
    if L > 1:
        alpha[0][1] = probs[0][extended[1]]

    for t in range(1, T):
        for s in range(L):
            val = alpha[t-1][s]
            if s >= 1:
                val += alpha[t-1][s-1]
            if s >= 2 and extended[s] != blank and extended[s] != extended[s-2]:
                val += alpha[t-1][s-2]
            alpha[t][s] = val * probs[t][extended[s]]

    p = alpha[T-1][L-1]
    if L > 1:
        p += alpha[T-1][L-2]
    return p

