def ctc_greedy_decode(log_probs, blank=0):
    path = np.argmax(log_probs, axis=-1)
    result = []
    prev = None
    for p in path:
        if p != prev and p != blank:
            result.append(int(p))
        prev = p
    return result

import numpy as np

def kl_divergence(mu, logvar):
    mu = np.asarray(mu, dtype=float)
    logvar = np.asarray(logvar, dtype=float)
    return -0.5 * np.sum(1 + logvar - mu**2 - np.exp(logvar))

import numpy as np

def preference_prob(r_a, r_b):
    r_a = np.asarray(r_a, dtype=float)
    r_b = np.asarray(r_b, dtype=float)
    return 1.0 / (1.0 + np.exp(-(r_a - r_b)))
